ALTER TABLE organization_commercial_terms
 DROP CONSTRAINT organization_commercial_terms_field_check,
 DROP CONSTRAINT organization_commercial_terms_value_check,
 ADD CONSTRAINT organization_commercial_terms_field_check CHECK (field IN ('hourly_rate','bonus_commission','currency_code')),
 ADD CONSTRAINT organization_commercial_terms_value_check CHECK (value IS NULL OR (field IN ('hourly_rate','bonus_commission') AND value ~ '^[0-9]{1,10}(\.[0-9]{1,6})?$') OR (field='currency_code' AND value ~ '^[A-Z]{3}$'));

CREATE OR REPLACE FUNCTION authorization_audit_summary_valid(audit_operation TEXT, summary JSONB)
RETURNS BOOLEAN LANGUAGE SQL IMMUTABLE PARALLEL SAFE AS $$
 SELECT CASE
  WHEN audit_operation='principal.register' THEN jsonb_typeof(summary)='object' AND summary ?& ARRAY['existed','identityCount','displayNamePresent','emailPresent'] AND summary-ARRAY['existed','identityCount','displayNamePresent','emailPresent']='{}'::jsonb AND jsonb_typeof(summary->'existed')='boolean' AND jsonb_typeof(summary->'displayNamePresent')='boolean' AND jsonb_typeof(summary->'emailPresent')='boolean' AND jsonb_typeof(summary->'identityCount')='number' AND summary->>'identityCount' ~ '^(0|[1-9][0-9]{0,17})$'
  WHEN audit_operation IN ('grants.grant','grants.revoke','grants.clear') THEN jsonb_typeof(summary)='object' AND summary ?& ARRAY['grantCount','selfCount','subtreeCount'] AND summary-ARRAY['grantCount','selfCount','subtreeCount']='{}'::jsonb AND jsonb_typeof(summary->'grantCount')='number' AND jsonb_typeof(summary->'selfCount')='number' AND jsonb_typeof(summary->'subtreeCount')='number' AND summary->>'grantCount' ~ '^(0|[1-9][0-9]{0,17})$' AND summary->>'selfCount' ~ '^(0|[1-9][0-9]{0,17})$' AND summary->>'subtreeCount' ~ '^(0|[1-9][0-9]{0,17})$'
  WHEN audit_operation IN ('profile.safe_write','organization.profile.safe_write','organization.status.safe_write','organization.commercial_terms.safe_write','organization.approved_to_hire.safe_write','organization.note.safe_write','organization.deletion.safe_write','pay_contract.create.safe_write','pay_contract.update.safe_write','pay_contract.remove.safe_write','candidate.bank_details.safe_write','organization.account_manager.safe_write') THEN jsonb_typeof(summary)='object' AND ((summary ?& ARRAY['valuePresent'] AND summary-ARRAY['valuePresent']='{}'::jsonb AND jsonb_typeof(summary->'valuePresent')='boolean') OR (summary ?& ARRAY['contractVersion','personRef','changeSetDigest','fields','committedAt','tokenRef'] AND summary-ARRAY['contractVersion','personRef','changeSetDigest','fields','committedAt','tokenRef']='{}'::jsonb AND jsonb_typeof(summary->'contractVersion')='string' AND summary->>'contractVersion' ~ '^[0-9]+\.[0-9]+\.[0-9]+$' AND jsonb_typeof(summary->'personRef')='string' AND summary->>'personRef' ~ '^[0-9a-f]{64}$' AND jsonb_typeof(summary->'changeSetDigest')='string' AND summary->>'changeSetDigest' ~ '^[0-9a-f]{64}$' AND jsonb_typeof(summary->'tokenRef')='string' AND summary->>'tokenRef' ~ '^[0-9a-f]{64}$' AND jsonb_typeof(summary->'fields')='array' AND jsonb_array_length(summary->'fields')=1 AND ((audit_operation='profile.safe_write' AND summary->'fields'='["language"]'::jsonb) OR (audit_operation='organization.profile.safe_write' AND summary->'fields'->>0 IN ('name_en','name_ar','description_en','description_ar','website')) OR (audit_operation='organization.status.safe_write' AND summary->'fields'='["status"]'::jsonb) OR (audit_operation='organization.commercial_terms.safe_write' AND summary->'fields'->>0 IN ('hourly_rate','bonus_commission','currency_code')) OR (audit_operation='organization.approved_to_hire.safe_write' AND summary->'fields'='["approved_to_hire"]'::jsonb) OR (audit_operation='organization.note.safe_write' AND summary->'fields'->>0 IN ('note','note_phone_call','note_email','note_meeting','note_interview','note_task')) OR (audit_operation='organization.deletion.safe_write' AND summary->'fields'='["deletion"]'::jsonb) OR (audit_operation='pay_contract.create.safe_write' AND summary->'fields'='["pay_contract"]'::jsonb) OR (audit_operation='pay_contract.update.safe_write' AND summary->'fields'='["pay_contract_terms"]'::jsonb) OR (audit_operation='pay_contract.remove.safe_write' AND summary->'fields'='["pay_contract_removal"]'::jsonb) OR (audit_operation='candidate.bank_details.safe_write' AND summary->'fields'='["bank_details"]'::jsonb) OR (audit_operation='organization.account_manager.safe_write' AND summary->'fields'='["account_manager"]'::jsonb)) AND jsonb_typeof(summary->'committedAt')='string' AND summary->>'committedAt' ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$'))
  WHEN audit_operation IN ('profile_record.create','profile_record.update','profile_record.remove','profile_record.restore','profile_record.replace') THEN jsonb_typeof(summary)='object' AND summary ?& ARRAY['kind','activeCount'] AND summary-ARRAY['kind','activeCount']='{}'::jsonb AND summary->>'kind' IN ('education','experience','skill','link') AND jsonb_typeof(summary->'activeCount')='number' AND summary->>'activeCount' ~ '^(0|[1-9][0-9]{0,17})$'
  WHEN audit_operation IN ('pay_contract.create','pay_contract.update','pay_contract.remove') THEN jsonb_typeof(summary)='object' AND summary ?& ARRAY['payModel','contractCount'] AND summary-ARRAY['payModel','contractCount']='{}'::jsonb AND summary->>'payModel' IN ('hourly','fixed_price','monthly_salary') AND jsonb_typeof(summary->'contractCount')='number' AND summary->>'contractCount' ~ '^(0|[1-9][0-9]{0,17})$'
  WHEN audit_operation IN ('organization.brand.link','organization.brand.unlink') THEN jsonb_typeof(summary)='object' AND summary ?& ARRAY['brandCount'] AND summary-ARRAY['brandCount']='{}'::jsonb AND jsonb_typeof(summary->'brandCount')='number' AND summary->>'brandCount' ~ '^(0|[1-9][0-9]{0,17})$'
  WHEN audit_operation='organization.create' THEN jsonb_typeof(summary)='object' AND summary ?& ARRAY['childCount'] AND summary-ARRAY['childCount']='{}'::jsonb AND jsonb_typeof(summary->'childCount')='number' AND summary->>'childCount' ~ '^(0|[1-9][0-9]{0,17})$'
  WHEN audit_operation IN ('organization.store.create','organization.store.update','organization.store.remove') THEN jsonb_typeof(summary)='object' AND summary ?& ARRAY['storeCount'] AND summary-ARRAY['storeCount']='{}'::jsonb AND jsonb_typeof(summary->'storeCount')='number' AND summary->>'storeCount' ~ '^(0|[1-9][0-9]{0,17})$'
  ELSE FALSE END
$$;
